(5280002, 769100, 41357, '<td valign="top">Judi is that you?<br/>long time no seen<br/>great picture<br/><br/><i>Message edited by author 2009-03-08 14:49:01.</i></td>', 'Judi is that you?long time no seengreat picture', '2009-03-01 00:15:27.000000', '2009-03-08 14:49:01.000000', 1),
(5280003, 769012, 81362, '<td valign="top">Having the bit of red balancing the bit of blue provides a welcome additional dimension of interest to the already interesting costume. Having the narrow shadows echo the narrow gloved finders is a nice bonus. Well done.</td>', 'Having the bit of red balancing the bit of blue provides a welcome additional dimension of interest to the already interesting costume. Having the narrow shadows echo the narrow gloved finders is a nice bonus. Well done.', '2009-03-01 00:15:41.000000', NULL, 1),
