(5281531, 768591, 22517, '<td valign="top">Beautiful reflection, I like the calmness of the water, good composition.</td>', 'Beautiful reflection, I like the calmness of the water, good composition.', '2009-03-01 17:17:32.000000', NULL, 1),
(5281533, 768750, 22517, '<td valign="top">Nice capture, great angle that conveys the message of speed very well.</td>', 'Nice capture, great angle that conveys the message of speed very well.', '2009-03-01 17:18:47.000000', NULL, 1),
(5281534, 768623, 22517, '<td valign="top">Wow, I really love the colours in this one. And the calmness of the water. Great composition and excellent processing. One of my favourites.</td>', 'Wow, I really love the colours in this one. And the calmness of the water. Great composition and excellent processing. One of my favourites.', '2009-03-01 17:19:56.000000', NULL, 1),
