(5281536, 769058, 22517, '<td valign="top">Excellent DOF and processing. The expression of the newborn is great. Choice of B/W is OK. Well done.</td>', 'Excellent DOF and processing. The expression of the newborn is great. Choice of B/W is OK. Well done.', '2009-03-01 17:22:07.000000', NULL, 1),
(5281538, 768592, 22517, '<td valign="top">Great contrast and excellent focusing/sharpness make this picture stand out from other sign pictures. Well done.</td>', 'Great contrast and excellent focusing/sharpness make this picture stand out from other sign pictures. Well done.', '2009-03-01 17:23:20.000000', NULL, 1),
(5281540, 769100, 36377, '<td valign="top">Outstanding</td>', 'Outstanding', '2009-03-01 17:24:48.000000', NULL, 1),
(5281544, 768169, 22517, '<td valign="top">I love the subject and angle and colours and composition (and wonder where it is)? A little more contrast and deeper blacks would have made this picture my absolute favourite. Still very well done, though!</td>', 'I love the subject and angle and colours and composition (and wonder where it is)? A little more contrast and deeper blacks would have made this picture my absolute favourite. Still very well done, though!', '2009-03-01 17:26:53.000000', NULL, 1),
(5281546, 769243, 22517, '<td valign="top">Very well captured, spot on DOF and clean background add to the quality of this picture. Well done.</td>', 'Very well captured, spot on DOF and clean background add to the quality of this picture. Well done.', '2009-03-01 17:27:51.000000', NULL, 1),
