(5281595, 767867, 92512, '<td valign="top">Good picture</td>', 'Good picture', '2009-03-01 17:59:03.000000', NULL, 1),
(5281598, 768178, 70514, '<td valign="top">I must say this image doesn''t convey a feeling of hope for me, but I''m in a funk :)  But I absolutely love this image, the contrasting colors and textures are wonderful.  I do like the hint of light through the glass, it''s cool and gritty.</td>', 'I must say this image doesn''t convey a feeling of hope for me, but I''m in a funk :)  But I absolutely love this image, the contrasting colors and textures are wonderful.  I do like the hint of light through the glass, it''s cool and gritty.', '2009-03-01 18:00:51.000000', NULL, 1),
(5281602, 769075, 70514, '<td valign="top">Absolutely beautiful.  The softness yet exquisite detail of the feathers, especially against the surroundings is so lovely.</td>', 'Absolutely beautiful.  The softness yet exquisite detail of the feathers, especially against the surroundings is so lovely.', '2009-03-01 18:01:49.000000', NULL, 1),
(5281603, 769084, 70514, '<td valign="top">Lovely lines, this is so pretty in b/w.</td>', 'Lovely lines, this is so pretty in b/w.', '2009-03-01 18:02:50.000000', NULL, 1),
(5281604, 769238, 92512, '<td valign="top">All the objects draws your eyes to the right edge. I would rather have them pulled into the image. But still a good work.</td>', 'All the objects draws your eyes to the right edge. I would rather have them pulled into the image. But still a good work.', '2009-03-01 18:04:01.000000', NULL, 1),
(5281605, 768711, 40430, '<td valign="top">if he were only riding into the frame not out of it, otherwise great job.</td>', 'if he were only riding into the frame not out of it, otherwise great job.', '2009-03-01 18:04:03.000000', NULL, 1),
(5281606, 764971, 40430, '<td valign="top">great colors and impact-10</td>', 'great colors and impact-10', '2009-03-01 18:04:43.000000', NULL, 1),
(5281610, 768547, 40430, '<td valign="top">Nice impressionistic effect.</td>', 'Nice impressionistic effect.', '2009-03-01 18:06:17.000000', NULL, 1),
(5281612, 766687, 40430, '<td valign="top">very sharp</td>', 'very sharp', '2009-03-01 18:06:52.000000', NULL, 1),
(5281614, 763367, 40430, '<td valign="top">where can you get these?</td>', 'where can you get these?', '2009-03-01 18:08:03.000000', NULL, 1),
