(5282631, 769125, 70000, '<td valign="top">Nice setting, i love the depth of field. The theme of girl in black angel wings has been done a lot, but I can''t just write this off because of that. The detailing of the snow in the foreground and background combined with an interesting, tighter composition works very well.</td>', 'Nice setting, i love the depth of field. The theme of girl in black angel wings has been done a lot, but I can''t just write this off because of that. The detailing of the snow in the foreground and background combined with an interesting, tighter composition works very well.', '2009-03-02 01:05:22.000000', NULL, 1),
(5282654, 769058, 42601, '<td valign="top">This is an unbelievably powerful image. Well done on a fantastic study.</td>', 'This is an unbelievably powerful image. Well done on a fantastic study.', '2009-03-02 01:11:41.000000', NULL, 1),
(5282657, 768572, 70000, '<td valign="top">Quirky! I like the processing and the perspective of this.</td>', 'Quirky! I like the processing and the perspective of this.', '2009-03-02 01:12:33.000000', NULL, 1),
(5282675, 768525, 70000, '<td valign="top">Her skin seems really unnaturally smooth here. The lighting setup is interesting but I am not a big fan of the pose.</td>', 'Her skin seems really unnaturally smooth here. The lighting setup is interesting but I am not a big fan of the pose.', '2009-03-02 01:20:13.000000', NULL, 1),
(5282706, 765858, 75585, '<td valign="top">Fantastic!!</td>', 'Fantastic!!', '2009-03-02 01:30:58.000000', NULL, 1),
(5282853, 768657, 34154, '<td valign="top">it''s too bad that her head disappears into the railing- otherwise a great shot-</td>', 'it''s too bad that her head disappears into the railing- otherwise a great shot-', '2009-03-02 03:44:49.000000', NULL, 1),
(5282859, 767658, 34154, '<td valign="top">i wish there were more photos like this on here-</td>', 'i wish there were more photos like this on here-', '2009-03-02 03:51:52.000000', NULL, 1),
