(5283061, 768793, 56254, '<td valign="top">I love the textures of the peeling paint ... great shot</td>', 'I love the textures of the peeling paint ... great shot', '2009-03-02 08:00:21.000000', NULL, 1),
(5283071, 768586, 68956, '<td valign="top">I love flies, they''re so beautiful and you''ve caught this one really well:)</td>', 'I love flies, they''re so beautiful and you''ve caught this one really well:)', '2009-03-02 08:08:23.000000', NULL, 1),
(5283075, 768316, 68956, '<td valign="top">Beautifully sharp and lovely composition, but isn''t it annoying when birds pose with twigs in front of them;)</td>', 'Beautifully sharp and lovely composition, but isn''t it annoying when birds pose with twigs in front of them;)', '2009-03-02 08:11:16.000000', NULL, 1),
(5283076, 767408, 68956, '<td valign="top">I hope Liz isn''t as sad as she looks. A good emotional image, with the muted colours and Liz looking away from us :)</td>', 'I hope Liz isn''t as sad as she looks. A good emotional image, with the muted colours and Liz looking away from us :)', '2009-03-02 08:13:13.000000', NULL, 1),
(5283077, 768729, 68956, '<td valign="top">Took me a moment, then I realised I''ve been there too:O ;) Very good, I like it :)</td>', 'Took me a moment, then I realised I''ve been there too:O ;) Very good, I like it :)', '2009-03-02 08:14:07.000000', NULL, 1),
(5283079, 768237, 14593, '<td valign="top">very nice...I like this a lot.   I don''t know how you got this fantastic angle, but it makes the photo unique.</td>', 'very nice...I like this a lot.   I don''t know how you got this fantastic angle, but it makes the photo unique.', '2009-03-02 08:17:56.000000', NULL, 1),
(5283080, 768403, 14593, '<td valign="top">nice dog photo...what a cute puppy!</td>', 'nice dog photo...what a cute puppy!', '2009-03-02 08:19:09.000000', NULL, 1),
(5283086, 768729, 14593, '<td valign="top">different..I had to take a second look at it...I used to ride the train every weekend from town to town, and this photo reminded me of it.</td>', 'different..I had to take a second look at it...I used to ride the train every weekend from town to town, and this photo reminded me of it.', '2009-03-02 08:20:55.000000', NULL, 1),
