(5291757, 768991, 92512, '<td valign="top">This is a very good macro wish you would have had more elements to it.</td>', 'This is a very good macro wish you would have had more elements to it.', '2009-03-05 19:49:07.000000', NULL, 1),
(5291764, 767729, 100106, '<td valign="top">Like how the BG is taken out of the picture. Just keep me focused on the two cuties. The great thing you have here is their body positions are not tense. They''re relaxed and soft which really shows me they''re talking to one another. Captured and conyed well. Overall a very pleasing photo. 8</td>', 'Like how the BG is taken out of the picture. Just keep me focused on the two cuties. The great thing you have here is their body positions are not tense. They''re relaxed and soft which really shows me they''re talking to one another. Captured and conyed well. Overall a very pleasing photo. 8', '2009-03-05 19:52:49.000000', NULL, 1),
(5291765, 767878, 100831, '<td valign="top">gorgeous!</td>', 'gorgeous!', '2009-03-05 19:53:03.000000', NULL, 1),
(5291768, 769031, 92512, '<td valign="top">Nice silhouette.  Not sure the title.  This looks a lot better than it does in the daylight.  I like it!</td>', 'Nice silhouette.  Not sure the title.  This looks a lot better than it does in the daylight.  I like it!', '2009-03-05 19:53:32.000000', NULL, 1),
(5291769, 767008, 84124, '<td valign="top">Absolutely beautiful!  I love shots that make me feel like I''m there, thanks for posting this.</td>', 'Absolutely beautiful!  I love shots that make me feel like I''m there, thanks for posting this.', '2009-03-05 19:54:07.000000', NULL, 1);
