(5294312, 767813, 62187, '<td valign="top">Oh, that''s got to be Lake Mead. A wonderful representation of it but scary to see the waterline so low. Don''t blame me, I have rocks in my yard!</td>', 'Oh, that''s got to be Lake Mead. A wonderful representation of it but scary to see the waterline so low. Don''t blame me, I have rocks in my yard!', '2009-03-07 14:27:08.000000', NULL, 1),
(5294314, 768750, 67237, '<td valign="top">very interesting idea and execution</td>', 'very interesting idea and execution', '2009-03-07 14:29:19.000000', NULL, 1),
(5294315, 764377, 61961, '<td valign="top">It''s hard to tell with such a high key image, but it seems the eyes are unnaturally painted white.  Lovely model though and an appealing image.</td>', 'It''s hard to tell with such a high key image, but it seems the eyes are unnaturally painted white.  Lovely model though and an appealing image.', '2009-03-07 14:29:42.000000', NULL, 1),
(5294318, 766769, 63812, '<td valign="top">wow! All her world is in her glance. Sadness, maturity and sweetness. Wonderful capture</td>', 'wow! All her world is in her glance. Sadness, maturity and sweetness. Wonderful capture', '2009-03-07 14:33:44.000000', NULL, 1),
