(5295284, 768431, 44877, '<td valign="top">I love this, Michelle! Excellent capture and great crop.</td>', 'I love this, Michelle! Excellent capture and great crop.', '2009-03-08 00:43:43.000000', NULL, 0),
(5295285, 767686, 50695, '<td valign="top">Lovely. 7</td>', 'Lovely. 7', '2009-03-08 00:43:51.000000', NULL, 0),
(5295286, 765655, 83313, '<td valign="top">Didn''t come up for me in voting, but I had to leave a comment on this one. A shame more people did not appreciate such a unique and creative entry. It really is different! I see you did appeal to <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=30364" rel="nofollow" target="_blank">Ubique</a>. The man is not easily impressed, so appealing to his artistic sense is as good as a ribbon in my book. And <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">Posthumous</a> liked it as well. Double whammy with this one! Congrats!<br/><br/><i>Message edited by author 2009-03-08 00:45:23.</i></td>', 'Didn''t come up for me in voting, but I had to leave a comment on this one. A shame more people did not appreciate such a unique and creative entry. It really is different! I see you did appeal to  Ubique. The man is not easily impressed, so appealing to his artistic sense is as good as a ribbon in my book. And  Posthumous liked it as well. Double whammy with this one! Congrats!', '2009-03-08 00:43:58.000000', '2009-03-08 00:45:23.000000', 0),
(5295287, 765295, 44877, '<td valign="top">Outstanding, Charlene - another beautiful BW from you. Very compelling image.</td>', 'Outstanding, Charlene - another beautiful BW from you. Very compelling image.', '2009-03-08 00:44:33.000000', NULL, 0),
(5295289, 769100, 67145, '<td valign="top">wow judi, this is superb .. just love the beautiful colouring and of course the pose, the scene and the incredible photography/processing .. congrats on the ribbon .. spose floods come in handy sometimes .. !! .. hope you guys are ok .. :)</td>', 'wow judi, this is superb .. just love the beautiful colouring and of course the pose, the scene and the incredible photography/processing .. congrats on the ribbon .. spose floods come in handy sometimes .. !! .. hope you guys are ok .. :)', '2009-03-08 00:45:24.000000', NULL, 0),
(5295290, 768724, 44877, '<td valign="top">Excellent photo!! Can''t believe it didn''t score higher. People probably don''t believe that the rocks are actually that color. This is really stunning.</td>', 'Excellent photo!! Can''t believe it didn''t score higher. People probably don''t believe that the rocks are actually that color. This is really stunning.', '2009-03-08 00:46:10.000000', NULL, 0),
(5295293, 767658, 83313, '<td valign="top">I think you nailed exactly what you were after with this. A Posthumous award and appeal to a limited group that likes such things. It did not come up for me in voting and I honestly don''t know what I would have given it. The appearance is clearly intentional. I congratulate you on being able to target your audience with such precision.<br/> <br/>Added: Also glad to see you jumping into the fray again.<br/><br/><i>Message edited by author 2009-03-08 00:50:30.</i></td>', 'I think you nailed exactly what you were after with this. A Posthumous award and appeal to a limited group that likes such things. It did not come up for me in voting and I honestly don''t know what I would have given it. The appearance is clearly intentional. I congratulate you on being able to target your audience with such precision. Added: Also glad to see you jumping into the fray again.', '2009-03-08 00:49:12.000000', '2009-03-08 00:50:30.000000', 0),
(5295294, 769100, 64670, '<td valign="top">WOW - this is amazing.</td>', 'WOW - this is amazing.', '2009-03-08 00:49:35.000000', NULL, 0),
(5295296, 764126, 27133, '<td valign="top">Very nicely done...and 100th place...woohoo!!!  It''s always nice to see round figures.</td>', 'Very nicely done...and 100th place...woohoo!!!  It''s always nice to see round figures.', '2009-03-08 00:50:00.000000', NULL, 0),
