INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5297379, 768417, 12250, '<td valign="top">Thank you for taking the time to comment.  I will definitely not give up trying the HDR thing.  It makes me excited learning each day what works and what doesn''t.  I hope to be a 6+ scorer by end of year.  <br/><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by Melethia:</b></div><hr/><i> Sometimes HDR works, sometimes not so much.  When you first start playing with it, it''s hard to tell.  One thing to check is how it looks as a thumbnail.  The overall grayish cast when you view the thumbnail is an indication (to me, anyway) that it may not work or is overdone.  Designed to balance out the high highs and low lows, sometimes it can make everything too much in the middle if that makes sense.  So don''t give up on it!  Keep playing with it, try different settings, etc, and find where it works, where it doesn''t.  I like the picture itself and would like to see it with more conventional editing - really a nice depiction of modern urban sprawl.  And yes, just verified from your info that this is SoCal.  Was about to write "looks like southern California..."  :-) </i></td></tr></table></td>', 'Thank you for taking the time to comment.  I will definitely not give up trying the HDR thing.  It makes me excited learning each day what works and what doesn''t.  I hope to be a 6+ scorer by end of year.  Originally posted by Melethia: Sometimes HDR works, sometimes not so much.  When you first start playing with it, it''s hard to tell.  One thing to check is how it looks as a thumbnail.  The overall grayish cast when you view the thumbnail is an indication (to me, anyway) that it may not work or is overdone.  Designed to balance out the high highs and low lows, sometimes it can make everything too much in the middle if that makes sense.  So don''t give up on it!  Keep playing with it, try different settings, etc, and find where it works, where it doesn''t.  I like the picture itself and would like to see it with more conventional editing - really a nice depiction of modern urban sprawl.  And yes, just verified from your info that this is SoCal.  Was about to write "looks like southern California..."  :-) ', '2009-03-09 11:00:58.000000', NULL, 0),
